const reanchor=(path,origin)=>{if(!path?.length)return[{...origin}];const out=[{...origin}];for(let i=1;i<path.length;i++)out.push({x:out[i-1].x+path[i].x-path[i-1].x,y:out[i-1].y+path[i].y-path[i-1].y});return out};
