const forceMove=(u,dir,n,units,size)=>{const d=dirs[dir],from={...u.position};let moved=0,blocked=false;if(!d)return{from,to:{...from},moved,blocked:true};for(let i=0;i<n;i++){const next={x:u.position.x+d.x,y:u.position.y+d.y};if(!inside(next,size)||units.some(o=>o.hp>0&&o.id!==u.id&&posKey(o.position)===posKey(next))){blocked=true;break}u.position=next;moved++}return{from,to:{...u.position},moved,blocked}};
