  const criticalCapable=action.kind==='일반공격'||action.kind==='스킬'&&!!def?.canCritical,damageCapable=action.kind==='일반공격'||action.kind==='스킬'&&def?.effects?.some(effect=>effect.type==='피해'),comboTarget=criticalCapable&&damageCapable?targets.find(t=>airborne.has(t.id)||t.statuses?.some(s=>['띄워짐','기절','에어본'].includes(s.type))):undefined;if(comboTarget){const source=airborne.get(comboTarget.id)||comboTarget.statuses.find(s=>['띄워짐','기절','에어본'].includes(s.type));if(source?.sourceId&&source.sourceId!==actor.id){r.state='연계';r.tone='combo';r.reason=(source.sourceName||'이전 행동')+' → '+actor.name+' 치명타 연계';r.combo={sourceId:source.sourceId,sourceName:source.sourceName,targetId:comboTarget.id,actorId:actor.id}}}
