   if(effect.type==='밀치기'||effect.type==='당기기'){const dir=effect.type==='당기기'?op[action.direction]:action.direction,move=forceMove(target,dir,effect.value,units,state.boardSize);target.statuses=(target.statuses||[]).filter(s=>s.type!=='띄워짐');target.statuses.push({type:'띄워짐',duration:1,sourceId:actor.id,sourceName:actor.name});airborne.set(target.id,{sourceId:actor.id,sourceName:actor.name});r.force={...move,type:effect.type,targetName:target.name};r.reactions.push({targetId:target.id,type:effect.type,value:move.moved,from:move.from,to:move.to});r.reason=effect.type+' '+move.moved+'/'+effect.value+'칸 · 띄워짐 부여'}
